<script>
export default {
  name: "HomeUser",
  props: {
    userInfo: { type: Object, default: () => ({}) },
  },
  data() {
    return {
      pendingCount: 0,
      leaveTypes: [
        {
          key: "cp",
          title: "Congés Payés",
          subtitle: "25 jours ouvrés par an",
          color: "#3f51b5",
          validated: 0,
          daysTaken: 0,
        },
        {
          key: "rtt",
          title: "RTT",
          subtitle: "Réduction du temps de travail",
          color: "#43a047",
          validated: 0,
          daysTaken: 0,
        },
        {
          key: "exceptional",
          title: "Congés Exceptionnels",
          subtitle: "Selon la règlementation (motif requis)",
          color: "#fb8c00",
          validated: 0,
          daysTaken: 0,
        },
        {
          key: "unpaid",
          title: "Congés Sans Solde",
          subtitle: "Sur autorisation préalable",
          color: "#757575",
          validated: 0,
          daysTaken: 0,
        },
      ],
    };
  },
  computed: {
    initials() {
      const name = this.userInfo?.user_name || "";
      return name
        .split(" ")
        .map((w) => w[0])
        .join("")
        .toUpperCase()
        .slice(0, 2) || "?";
    },
    hireDate() {
      const ts = parseInt(this.userInfo?.date_embauche_timestamp);
      if (!ts) return "—";
      return new Date(ts * 1000).toLocaleDateString("fr-FR", {
        day: "2-digit",
        month: "long",
        year: "numeric",
      });
    },
    rttEligible() {
      return this.userInfo?.eligibilite_RTT == 1;
    },
    seniorityUsed() {
      const total = parseInt(this.userInfo?.jour_anciennete_total) || 0;
      const dispo = parseInt(this.userInfo?.jour_anciennete_dispo) || 0;
      return Math.max(0, total - dispo);
    },
    seniorityPercent() {
      const total = parseInt(this.userInfo?.jour_anciennete_total) || 0;
      if (total === 0) return 0;
      return Math.round((this.seniorityUsed / total) * 100);
    },
  },
  methods: {
    pad(n) {
      return String(n).padStart(2, "0");
    },
    onCardClick(leave) {
      this.$emit("open-details", leave);
    },
  },
};
</script>

