<script>
export default {
  name: "HomeAdmin",
  props: {
    userInfo: { type: Object, default: () => ({}) },
  },
  data() {
    return {
      pendingRequests: [],
      allRequests: [],
      stats: [
        {
          label: "Total demandes",
          value: 0,
          color: "#3f51b5",
          icon: "mdi-calendar-text",
        },
        {
          label: "En attente",
          value: 0,
          color: "#fb8c00",
          icon: "mdi-clock-outline",
        },
        {
          label: "Validées",
          value: 0,
          color: "#43a047",
          icon: "mdi-check-circle",
        },
        {
          label: "Refusées",
          value: 0,
          color: "#e53935",
          icon: "mdi-close-circle",
        },
      ],
    };
  },
  methods: {
    getLeaveColor(type) {
      const map = {
        "Congés Payés": "#3f51b5",
        RTT: "#43a047",
        "Congés Exceptionnels": "#fb8c00",
        "Congés Sans Solde": "#757575",
      };
      return map[type] || "#3f51b5";
    },
    getStatusColor(status) {
      const map = {
        Validée: "#43a047",
        Refusée: "#e53935",
        "En attente": "#fb8c00",
      };
      return map[status] || "#757575";
    },
    approveRequest(req) {
      this.$emit("approve", req);
    },
    rejectRequest(req) {
      this.$emit("reject", req);
    },
    viewRequest(req) {
      this.$emit("view-request", req);
    },
  },
};
</script>

